text.script:
'use strict';
export var scriptProperties = createScriptProperties()
    .addCheckbox({ name: 'seconds', label: 'Seconds', value: false })
    .addText({ name: 'separator', label: 'Separator', value: ':' })
    .finish();
const pad = n => ('0' + n).slice(-2);
export function update(value) {
    const t = new Date();
    let s = pad(t.getHours()) + scriptProperties.separator + pad(t.getMinutes());
    if (scriptProperties.seconds) s += scriptProperties.separator + pad(t.getSeconds());
    return s;
}

origin.script:
'use strict';
import * as WEMath from 'WEMath';
// The group (with the date as its child) slides right over the first two seconds.
export function update(value) {
    value.x = WEMath.mix(300, 700, WEMath.smoothStep(0, 2, engine.runtime));
    return value;
}

text.script:
'use strict';
const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
export function init() {
    const t = new Date();
    return days[t.getDay()] + ' ' + t.getFullYear() + '-' + (t.getMonth() + 1) + '-' + t.getDate();
}

visible.script:
'use strict';
export function init() { shared.hideWarning = true; }
export function update(value) { return true; }

color.script:
'use strict';
import * as WEColor from 'WEColor';
// Hue from the time of day (12:34:56 -> 0.524), turning a little every second.
export function update(value) { return WEColor.hsv2rgb(new Vec3((engine.timeOfDay + engine.runtime * 0.1) % 1, 0.8, 1)); }

text.script:
'use strict';
let n = 0;
export function init() { engine.setInterval(() => { n += 1; }, 500); }
export function update(value) { return 'ticks: ' + n + ' / ' + engine.canvasSize.x + 'x' + engine.canvasSize.y; }
